<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {matSave,matRefresh} from '@quasar/extras/material-icons'
import {request} from '../lib/api'
import type {Policy} from '../types'
interface Settings {policy:Policy;retention_days:number;max_concurrent_jobs:number;max_supported_concurrent_jobs?:number;auth_mode:'local'|'access';public_origin:string;version:string}
const data=ref<Settings|null>(null),loading=ref(true),saving=ref(false),error=ref(''),saved=ref(false),confirmRetention=ref(false)
let originalRetention=0;const controller=new AbortController()
const fields=[['max_targets','Maximum address upper bound'],['max_rate','Maximum discovery rate'],['max_threads','Maximum discovery threads'],['max_host_workers','Maximum host workers'],['max_http_requests','Maximum simultaneous HTTP requests'],['max_http_per_host','Maximum HTTP requests per host'],['max_http_rps','Maximum HTTP requests per second'],['max_retry','Maximum discovery retries'],['max_wait','Maximum discovery wait (seconds)'],['max_timeout_seconds','Maximum job deadline (seconds)'],['max_host_timeout_seconds','Maximum host deadline (seconds)']]
const permissions=[['allow_raw','Permit raw discovery','Raw execution also requires an explicitly enabled, capable runner and server capability.'],['allow_credentials','Permit credential checks','Every job still requires its own explicit opt-in and an encrypted credential set.'],['allow_capture','Permit HTTP still-image capture','Every job still requires a capture opt-in.'],['allow_onvif','Permit ONVIF UDP discovery','UDP is not routed through the HTTP proxy.'],['allow_unpaced_http','Permit unpaced HTTP','Allows a job to set HTTP requests per second to zero. Other request limits still apply.']]
const required=(v:unknown)=>v!==''&&v!==null&&Number.isFinite(Number(v))||'Enter a finite number.'
function limit(key:string,v:string|number|null){if(data.value)data.value.policy[key]=v===''||v===null?Number.NaN:Number(v);saved.value=false}
async function load(){loading.value=true;error.value='';saved.value=false;try{const s=await request<Settings>('/settings',{signal:controller.signal});data.value=s;originalRetention=s.retention_days}catch(e){if(!controller.signal.aborted)error.value=e instanceof Error?e.message:'Settings could not be loaded.'}finally{loading.value=false}}
async function save(confirmed=false){if(!data.value||saving.value)return;if(data.value.retention_days<originalRetention&&!confirmed){confirmRetention.value=true;return}saving.value=true;error.value='';saved.value=false;try{const d=data.value;const s=await request<Settings>('/settings',{method:'PUT',body:{policy:d.policy,retention_days:Number(d.retention_days),max_concurrent_jobs:Number(d.max_concurrent_jobs)},signal:controller.signal});data.value=s;originalRetention=s.retention_days;saved.value=true;confirmRetention.value=false}catch(e){if(!controller.signal.aborted)error.value=e instanceof Error?e.message:'Settings could not be saved.'}finally{saving.value=false}}
onMounted(load);onBeforeUnmount(()=>controller.abort())
</script>
<template>
 <q-page class="workspace settings-workspace"><header class="page-header"><div><p class="page-kicker">Control plane</p><h1>Settings</h1><p class="page-description">Server policy, retention and execution bounds. Secrets stay on the server.</p></div><q-btn flat round :icon="matRefresh" :loading="loading" aria-label="Reload server settings" @click="load"/></header>
  <div v-if="error" role="alert" class="error-banner">{{error}}</div><p v-if="saved" role="status" class="saved-message">Settings saved. New work is validated against the current server policy.</p><p v-if="loading&&!data" class="loading-label" role="status">Loading current server settings…</p>
  <q-form v-if="data" class="settings-layout" @submit="save(false)"><div class="surface settings-form"><section class="form-section"><h2>Execution &amp; retention</h2><p class="helper q-mb-lg">Existing job snapshots are not rewritten. Reducing retention allows cleanup to remove expired evidence.</p><div class="form-grid two-col"><q-input v-model.number="data.max_concurrent_jobs" type="number" outlined label="Maximum simultaneous jobs" :min="1" :max="data.max_supported_concurrent_jobs??1" :rules="[required,v=>Number(v)>=1&&Number(v)<=(data?.max_supported_concurrent_jobs??1)||'Choose a value supported by this server.']" :hint="`Current server capability: ${data.max_supported_concurrent_jobs??1}. Runner availability can further limit execution.`"/><q-input v-model.number="data.retention_days" name="retention_days" type="number" outlined label="Retention (days)" min="1" max="3650" :rules="[required,v=>Number.isInteger(Number(v))&&Number(v)>=1&&Number(v)<=3650||'Use 1–3650 whole days.']"/></div></section><section class="form-section"><h2>Per-job ceilings</h2><p class="helper q-mb-lg">Jobs must fit these limits as well as the scanner's own bounds. The server rejects values beyond its hard capability ceilings.</p><div class="form-grid three-col"><q-input v-for="[key,label] in fields" :key="key" :model-value="Number.isFinite(data.policy[key])?data.policy[key] as number:''" @update:model-value="limit(key,$event)" type="number" min="0" step="any" outlined :label="label" :rules="[required,v=>Number(v)>=0||'Use zero or a positive ceiling.']"/></div></section><section class="form-section"><h2>Permission boundaries</h2><p class="helper q-mb-lg">These permissions never enable a sensitive action inside a job automatically.</p><div v-for="[key,label,help] in permissions" :key="key" class="permission-row"><q-toggle :model-value="data.policy[key]===true" @update:model-value="data.policy[key]=$event;saved=false" color="dark" :label="label"/><p class="helper">{{help}}</p></div></section><footer class="settings-save"><q-btn data-testid="save-settings" type="submit" unelevated color="primary" text-color="dark" :icon="matSave" label="Save settings" :loading="saving"/></footer></div>
   <aside class="settings-aside"><section class="surface access-panel"><span class="section-label">Access boundary</span><h2 data-testid="access-mode">{{data.auth_mode==='access'?'Cloudflare Access':'Local development'}}</h2><p v-if="data.auth_mode==='access'" class="helper">Sign-in is handled by Cloudflare Access.</p><p v-else class="safe-note">Cloudflare Access is not enabled in this mode. The API requires a loopback bind and local requests. Do not publish this development service.</p><dl class="metadata-list q-mt-lg"><div><dt>Public origin</dt><dd class="mono">{{data.public_origin}}</dd></div><div><dt>Version</dt><dd>{{data.version}}</dd></div></dl></section><section class="surface q-mt-lg access-panel"><h2>Encryption &amp; routing</h2><p class="helper q-mt-md">Key material is supplied server-side and is never shown or edited in browser settings. Proxy URLs and credential content are write-only.</p><p class="helper q-mt-md">HTTP proxying is not OS-wide egress isolation. Raw discovery, RTSP, UDP and private media/dependency traffic have separate routing requirements.</p></section></aside>
  </q-form>
  <q-dialog v-model="confirmRetention"><q-card class="retention-dialog"><q-card-section><h2>Shorten retention?</h2><p class="q-mt-md">Expired jobs and their stored evidence may be removed by cleanup. Keep a backup if you need historical records.</p></q-card-section><q-card-actions align="right"><q-btn flat label="Keep editing" v-close-popup/><q-btn unelevated color="negative" label="Save shorter retention" :loading="saving" @click="save(true)"/></q-card-actions></q-card></q-dialog>
 </q-page>
</template>
<style scoped>.settings-workspace{max-width:1500px}.settings-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px;align-items:start}.settings-form{padding:28px}.settings-save{padding-top:22px;border-top:1px solid var(--line)}.permission-row{padding:10px 0}.permission-row>.helper{margin-left:50px;max-width:56ch}.access-panel{padding:24px}.access-panel h2{font-size:22px;margin-top:20px;margin-bottom:16px}.access-panel .mono{font-size:11px}.saved-message{padding:16px 20px;background:#dfebe2;color:#244d36;border-radius:8px;margin-bottom:24px}.retention-dialog{max-width:440px;padding:12px}@media(max-width:1200px){.settings-layout{grid-template-columns:1fr}.settings-aside{display:grid;grid-template-columns:1fr 1fr;gap:20px}.settings-aside>.q-mt-lg{margin-top:0}}@media(max-width:700px){.settings-form{padding:22px 18px}.settings-aside{grid-template-columns:1fr}.permission-row>.helper{margin-left:12px}}</style>
